function adjustRestoreSnapshot(s){if(!s)return;adjustState.settings=Object.assign({},ADJUST_DEFAULTS,s.settings||{});adjustState.rotate=Number(s.rotate||0);adjustState.flipX=s.flipX===-1?-1:1;adjustState.flipY=s.flipY===-1?-1:1;adjustState.crop=s.crop||'original';adjustState.brushes=JSON.parse(JSON.stringify(s.brushes||adjustDefaultBrushes()));adjustState.activeBrush=s.activeBrush||'red';adjustState.brushSize=Number(s.brushSize||28);adjustState.brushTool=s.brushTool||'brush';adjustState.strokes=JSON.parse(JSON.stringify(s.strokes||[]));adjustState.showAnnotations=s.showAnnotations!==false;adjustState.exportAnnotations=s.exportAnnotations!==false;adjustState.autoSelectColor=false;adjustState.simpleMode=s.simpleMode!==false;adjustState.maskFeather=Number(s.maskFeather??6);adjustState.maskExpand=Number(s.maskExpand??0);adjustState.candidateCount=Math.max(2,Math.min(4,Number(s.candidateCount||3)));adjustState.queueOrder=Array.isArray(s.queueOrder)?s.queueOrder.slice():ADJUST_BRUSH_DEFS.map(x=>x.id);adjustState.dependencies=Object.assign({red:'',amber:'',green:'',blue:'',purple:''},s.dependencies||{});adjustState.guideMode=s.guideMode!==false;adjustState.guideStep=Math.max(1,Math.min(3,Number(s.guideStep||1)));adjustState.regionAiTasks=JSON.parse(JSON.stringify(s.regionAiTasks||[]));adjustState.regionPromptVersion=s.regionPromptVersion||'V27.9';adjustState.microBaseMode=(s.microBaseMode==='original'?'original':'current');adjustState.paramRecommendation=s.paramRecommendation||'尚未应用推荐参数';renderAdjustView();}
function adjustRefreshHistoryButtons(){const u=$('adj-undo'),r=$('adj-redo'),n=$('adj-history-count');if(u)u.disabled=adjustState.historyIndex<=0;if(r)r.disabled=adjustState.historyIndex<0||adjustState.historyIndex>=adjustState.history.length-1;if(n)n.textContent=adjustState.history.length?`${adjustState.historyIndex+1}/${adjustState.history.length}`:'0/0';}
function adjustCropRatio(code){if(code==='1:1')return 1;if(code==='3:4')return 3/4;if(code==='4:3')return 4/3;if(code==='9:16')return 9/16;if(code==='16:9')return 16/9;return null;}
function adjustCropRect(img,code){let x=0,y=0,w=img.naturalWidth||img.width,h=img.naturalHeight||img.height;const ratio=adjustCropRatio(code);if(!ratio)return{x,y,w,h};const current=w/h;if(current>ratio){const nw=h*ratio;x=(w-nw)/2;w=nw;}else{const nh=w/ratio;y=(h-nh)/2;h=nh;}return{x,y,w,h};}
function adjustFilter(original,scale){if(original)return'none';const s=adjustState.settings;return `brightness(${Math.max(0,100+s.brightness)}%) contrast(${Math.max(0,100+s.contrast)}%) saturate(${Math.max(0,100+s.saturation)}%) hue-rotate(${s.hue}deg) blur(${Math.max(0,s.blur)*(scale||1)}px)`;}
