function adjustDraw(canvas,full,original,includeAnnotations=true){const img=adjustState.img;if(!canvas||!img)return null;const crop=adjustCropRect(img,adjustState.crop),angle=((adjustState.rotate%360)+360)%360,swap=angle===90||angle===270;let outW=swap?crop.h:crop.w,outH=swap?crop.w:crop.h,scale=1;if(!full)scale=Math.min(1,1050/outW,720/outH);canvas.width=Math.max(1,Math.round(outW*scale));canvas.height=Math.max(1,Math.round(outH*scale));const ctx=canvas.getContext('2d',{alpha:true});ctx.clearRect(0,0,canvas.width,canvas.height);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(angle*Math.PI/180);ctx.scale(adjustState.flipX,adjustState.flipY);ctx.filter=adjustFilter(original,full?1:scale);ctx.drawImage(img,crop.x,crop.y,crop.w,crop.h,-crop.w*scale/2,-crop.h*scale/2,crop.w*scale,crop.h*scale);ctx.restore();if(!original&&adjustState.settings.warmth){ctx.save();ctx.globalCompositeOperation='soft-light';const a=Math.min(.18,Math.abs(adjustState.settings.warmth)/100*.18);ctx.fillStyle=adjustState.settings.warmth>0?`rgba(255,133,55,${a})`:`rgba(60,132,255,${a})`;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.restore();}if(!original&&includeAnnotations)adjustDrawAnnotations(ctx,canvas,full&&adjustState.exportAnnotations);return{width:canvas.width,height:canvas.height,sourceWidth:crop.w,sourceHeight:crop.h};}
function adjustCanvasPoint(c,e){const r=c.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/Math.max(1,r.width))),y:Math.max(0,Math.min(1,(e.clientY-r.top)/Math.max(1,r.height))),size:Math.max(.004,adjustState.brushSize/Math.max(1,Math.min(r.width,r.height)))};}
function adjustBindBrushCanvas(c){if(!c||c.__adjustBrushBound)return;c.__adjustBrushBound=true;const start=e=>{if(!adjustState.img||adjustState.previewOriginal||adjustState.aiBusy)return;e.preventDefault();c.setPointerCapture&&c.setPointerCapture(e.pointerId);const p=adjustCanvasPoint(c,e);adjustState.drawing=true;adjustState.currentStroke={brushId:adjustState.activeBrush,tool:adjustState.brushTool,size:p.size,points:[{x:p.x,y:p.y}]};adjustState.strokes.push(adjustState.currentStroke);adjustRenderCanvas();};const move=e=>{if(!adjustState.drawing||!adjustState.currentStroke)return;e.preventDefault();const p=adjustCanvasPoint(c,e),pts=adjustState.currentStroke.points,last=pts[pts.length-1];if(!last||Math.hypot(p.x-last.x,p.y-last.y)>.002){pts.push({x:p.x,y:p.y});adjustRenderCanvas();}};const end=e=>{if(!adjustState.drawing)return;e.preventDefault();const finishedId=adjustState.currentStroke&&adjustState.currentStroke.brushId,wasBrush=adjustState.brushTool!=='eraser';adjustState.drawing=false;adjustState.currentStroke=null;adjustPushHistory(adjustState.brushTool==='eraser'?'擦除标注':'添加'+adjustBrushDef(adjustState.activeBrush).label+'标注');adjustRefreshBrushSummary();};c.addEventListener('pointerdown',start);c.addEventListener('pointermove',move);c.addEventListener('pointerup',end);c.addEventListener('pointercancel',end);c.addEventListener('pointerleave',e=>{if(e.buttons===0)end(e);});}
