function adjustRecommendTemplate(prompt){const s=String(prompt||'');if(/删除|去掉|移除|水印|文字/.test(s))return'remove-text';if(/替换|改成|换成/.test(s))return'replace-content';if(/颜色|色调|变色|渐变|背景/.test(s))return'adjust-color';if(/移动|左移|右移|上移|下移|位置/.test(s))return'move-subject';if(/材质|清晰|质感|锐化|细节|光影/.test(s))return'enhance-material';return'';}

