function adjustRegionTaskType(id){const b=adjustState.brushes[id]||{},t=b.template||adjustRecommendTemplate(b.prompt||'');return ADJUST_REGION_TYPE_META[t]?t:'custom';}
function adjustDependencySatisfied(id){const dep=adjustState.dependencies&&adjustState.dependencies[id];if(!dep)return true;return ['confirmed','skipped'].includes(adjustState.queueStatus[dep]);}
function adjustDependencyCycle(){const seen=new Set(),stack=new Set();function visit(id){if(stack.has(id))return true;if(seen.has(id))return false;seen.add(id);stack.add(id);const d=adjustState.dependencies[id];if(d&&visit(d))return true;stack.delete(id);return false;}return ADJUST_BRUSH_DEFS.some(b=>visit(b.id));}
function adjustApplyDependencyOrder(silent){if(adjustDependencyCycle()){if(!silent)setActionStatus('error','区域依赖存在循环，请重新选择前置区域',false);return false;}const ids=adjustState.queueOrder.slice(),out=[],vis=new Set();function add(id){if(vis.has(id))return;const d=adjustState.dependencies[id];if(d)add(d);vis.add(id);out.push(id);}ids.forEach(add);adjustState.queueOrder=out.filter((x,i,a)=>a.indexOf(x)===i);if(!silent){adjustPushHistory('按依赖关系重排队列');renderAdjustView();setActionStatus('success','已按区域依赖关系重排执行顺序',false);}return true;}
function adjustAutoDependencies(){const ordered=ADJUST_BRUSH_DEFS.map(b=>b.id).sort((a,b)=>ADJUST_REGION_TYPE_META[adjustRegionTaskType(a)].priority-ADJUST_REGION_TYPE_META[adjustRegionTaskType(b)].priority);const usable=new Set(adjustUsableColorIds());adjustState.queueOrder=ordered;let prev='';ordered.forEach(id=>{adjustState.dependencies[id]=usable.has(id)?prev:'';if(usable.has(id))prev=id;});adjustApplyDependencyOrder(true);adjustPushHistory('自动建立区域依赖');renderAdjustView();setActionStatus('success','已按“删除文字 → 内容/背景 → 移动主体 → 提升材质”建立依赖',false);}
function adjustDependencyHtml(){const usable=new Set(adjustUsableColorIds());return `<div class="adjust-dependency"><div class="adjust-dependency-head"><div><b>区域依赖关系设置</b><div class="hint">指定当前区域必须在某个区域确认后执行，避免后续修改破坏前序结果。</div></div><div class="row"><button class="mini-btn" data-adj-auto-deps>智能建立依赖</button><button class="mini-btn" data-adj-apply-deps>按依赖重排</button></div></div><div class="adjust-dependency-grid">${adjustState.queueOrder.map(id=>{const b=adjustBrushDef(id),type=adjustRegionTaskType(id),dep=adjustState.dependencies[id]||'';return `<div class="adjust-dependency-item" style="--dep-color:${b.color}"><div class="head"><span class="dot"></span><b>${esc(b.label)}</b><span class="wf-status-chip ${usable.has(id)?'ok':'wait'}">${esc(ADJUST_REGION_TYPE_META[type].label)}</span></div><select data-adj-dependency="${id}" ${adjustState.queueRunning?'disabled':''}><option value="">无前置区域</option>${ADJUST_BRUSH_DEFS.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${dep===x.id?'selected':''}>完成 ${esc(x.label)} 后执行</option>`).join('')}</select><small>${dep?'依赖：'+esc(adjustBrushDef(dep).label):'可独立执行'} · ${usable.has(id)?'已具备标注与指令':'尚未具备完整任务'}</small></div>`;}).join('')}</div></div>`;}
function adjustGuideHtml(){if(!adjustState.guideMode)return'';const usable=adjustUsableColorIds(),marks=adjustState.strokes.filter(s=>s.tool!=='eraser').length,steps=[['标记区域',marks?marks+' 笔标注':'在图片上涂抹'],['填写要求',usable.length?usable.length+' 个区域已就绪':'填写对应修改要求'],['选择结果',adjustState.candidateBatch?'候选已生成':'生成并选用候选']];return `<div class="adjust-guide"><div class="adjust-guide-steps">${steps.map((s,i)=>`<button type="button" class="adjust-guide-step ${adjustState.guideStep===i+1?'on':''}" data-adj-guide-step="${i+1}"><b>${i+1}. ${s[0]}</b><span>${s[1]}</span></button>`).join('')}</div><div class="adjust-guide-actions"><button class="btn btn-ghost" data-adj-guide-prev ${adjustState.guideStep<=1?'disabled':''}>上一步</button><button class="btn btn-violet" data-adj-guide-next>${adjustState.guideStep>=3?'生成候选':'下一步'}</button></div></div>`;}
function adjustGuideSetStep(step){step=Math.max(1,Math.min(3,Number(step)||1));if(step>=2&&!adjustState.strokes.some(s=>s.tool!=='eraser')){setActionStatus('error','请先在图片上标记至少一个修改区域',false);return false;}if(step>=3&&!adjustUsableColorIds().length){setActionStatus('error','请为已标记区域填写修改要求',false);return false;}adjustState.guideStep=step;if(step===3)adjustState.simpleMode=true;renderAdjustView();return true;}
function adjustRecommendParameters(){const ids=adjustUsableColorIds().length?adjustUsableColorIds():[adjustState.activeBrush],types=ids.map(adjustRegionTaskType),metas=types.map(t=>ADJUST_REGION_TYPE_META[t]||ADJUST_REGION_TYPE_META.custom);adjustState.maskFeather=Math.max(...metas.map(x=>x.feather));adjustState.maskExpand=Math.max(...metas.map(x=>x.expand));adjustState.candidateCount=Math.max(...metas.map(x=>x.count));adjustState.paramRecommendation=`${[...new Set(metas.map(x=>x.label))].join(' + ')}：羽化 ${adjustState.maskFeather}px，扩张 ${adjustState.maskExpand}px，候选 ${adjustState.candidateCount} 个`;adjustAutoDependencies();setActionStatus('success','已根据当前任务类型推荐 Mask 与候选参数',false);}
function adjustParseStrictJson(raw){let s=String(raw||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim();const a=s.indexOf('{'),b=s.lastIndexOf('}');if(a>=0&&b>a)s=s.slice(a,b+1);return JSON.parse(s);}
